"use strict";

// RWF-025. This module is RWF-024's fixture with ONE statement added, and
// that statement is the whole case:
//
//     ({ [keyFor(bail)]: seen } = REGISTRY);
//
// It is an ordinary destructuring assignment. It runs on every load, it
// completes normally, it rebinds exactly one local binding -- `seen` --
// and it has nothing whatever to do with the branch below or with the
// vulnerable package. `bail` appears in it only as an ARGUMENT to the
// key-producing call: the computed property name selects WHICH property of
// `REGISTRY` is read, it is not an assignment destination.
//
// The reassigned-name collector used to record EVERY identifier under an
// assignment target, so it recorded `bail` (and `keyFor`) as locally
// reassigned. That set is cached per SOURCE FILE, so this one statement
// made `bail`'s identity unresolvable for the WHOLE file, silently
// withdrawing the RWF-024 cutoff below and handing `module.exports =
// safeOp` an authority it does not have.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw -- definitely abrupt by RWF-016's own model, unchanged.
function bail() {
  throw new Error("fast mode is not supported here");
}

// A harmless local callable that turns a function into a registry key. It
// RETURNS NORMALLY, and it is the reason the poisoning statement below is
// harmless at runtime: nothing in it ever calls `bail`.
function keyFor(fn) {
  return "handler:" + fn.name;
}

const REGISTRY = { "handler:bail": "registered" };
let seen;

// THE POISON. Real `node` runs this to completion on every load: it
// evaluates `keyFor(bail)` to the string "handler:bail", reads that
// property off `REGISTRY`, and binds the result to `seen`. Neither `bail`
// nor `keyFor` is rebound by it -- only `seen` is.
({ [keyFor(bail)]: seen } = REGISTRY);
void seen;

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // RWF-024's cutoff, unchanged: an object literal's computed keys
  // evaluate in source order as the literal is constructed, so reaching
  // this declaration necessarily invokes `bail()`, which never returns.
  // `mode` is never bound and module evaluation on this branch ends here.
  const mode = {
    [keyFor(safeOp)]: "fast",
    [bail()]: 1,
  };
  void mode;
}

module.exports = safeOp;
